// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILineAxis {
    function balanceOf(address owner) external view returns (uint256);
    function transfer(address to, uint256 value) external;
    function transferFrom(address from, address to, uint256 value) external;
    function approve(address spender, uint256 value) external;
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);
    ILineAxis token;
    uint256 originalBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = ILineAxis(TARGET);
        vm.label(TARGET, "LineAxis Token");
        vm.label(attacker, "Attacker");

        // Inject tokens by directly setting balance in storage
        // _balanceOf is at slot 2 due to inheritance (Owned has _owner slot 0, _newOwner slot 1)
        bytes32 balanceSlot = keccak256(abi.encode(attacker, uint256(2)));
        vm.store(TARGET, balanceSlot, bytes32(uint256(10000 * 1e18)));

        originalBalance = token.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record balance before transfer
        uint256 balanceBefore = token.balanceOf(attacker);
        assertEq(balanceBefore, originalBalance, "Initial balance should match injected amount");

        // Execute transfer - this succeeds but returns NO BOOLEAN (ERC20 non-compliance!)
        // A standard ERC20 would return true, but this returns nothing
        address recipient = address(0xDEADBEEF);
        uint256 transferAmount = 1000 * 1e18;
        token.transfer(recipient, transferAmount);

        // Verify balance decreased (transfer executed successfully)
        uint256 balanceAfter = token.balanceOf(attacker);
        assertEq(balanceAfter, balanceBefore - transferAmount, "Balance should decrease after transfer");

        // Verify recipient received tokens
        uint256 recipientBalance = token.balanceOf(recipient);
        assertEq(recipientBalance, transferAmount, "Recipient should receive transferred tokens");

        // Oracle check: balance changed from original (demonstrating transfer worked despite no return value)
        assertGt(originalBalance, balanceAfter, "Oracle: Balance should be different after transfer");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

